package com.example.demo.request;

import com.example.demo.user.*;import jakarta.transaction.Transactional;import jakarta.validation.Valid;import jakarta.validation.constraints.*;
import org.springframework.core.io.*;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.web.server.ResponseStatusException;
import java.time.Instant;import java.util.*;

@RestController @RequestMapping("/api/requests")
public class RequestWorkflowController {
 private final MaintenanceRequestRepository requests;private final RequestWorkflowService workflow;private final UserRepository users;private final RequestHistoryRepository histories;private final AttachmentStorage files;
 public RequestWorkflowController(MaintenanceRequestRepository r,RequestWorkflowService w,UserRepository u,RequestHistoryRepository h,AttachmentStorage f){requests=r;workflow=w;users=u;histories=h;files=f;}
 @GetMapping("/manage") public List<Dto> manage(@AuthenticationPrincipal User u,@RequestParam(required=false) MaintenanceRequest.Status status,@RequestParam(required=false) MaintenanceRequest.Priority priority,@RequestParam(required=false) Long assignee,@RequestParam(required=false) String search){if(u.getRole()!=User.Role.ADMIN)deny();return requests.findAllByOrderByCreatedAtDesc().stream().filter(r->status==null||r.getStatus()==status).filter(r->priority==null||r.getPriority()==priority).filter(r->assignee==null||(r.getAssignee()!=null&&r.getAssignee().getId().equals(assignee))).filter(r->search==null||search.isBlank()||r.getTitle().toLowerCase().contains(search.toLowerCase())||r.getLocation().toLowerCase().contains(search.toLowerCase())).map(Dto::from).toList();}
 @GetMapping("/assigned") public List<Dto> assigned(@AuthenticationPrincipal User u){if(u.getRole()!=User.Role.STAFF||u.isMustChangePassword())deny();return requests.findByAssigneeIdOrderByCreatedAtDesc(u.getId()).stream().map(Dto::from).toList();}
 @GetMapping("/{id}") public Detail detail(@AuthenticationPrincipal User u,@PathVariable Long id){MaintenanceRequest r=workflow.requireVisible(id,u);List<HistoryDto> h=histories.findByRequestIdOrderByCreatedAtAsc(id).stream().map(HistoryDto::from).toList();return new Detail(Dto.from(r),r.getDescription(),r.getRepairNote(),r.getCompletedAt(),h);}
 @PatchMapping("/{id}") @Transactional public Dto edit(@AuthenticationPrincipal User u,@PathVariable Long id,@Valid @RequestBody Edit body){MaintenanceRequest r=workflow.requireVisible(id,u);if(u.getRole()!=User.Role.STUDENT||r.getStatus()!=MaintenanceRequest.Status.PENDING||r.getAssignee()!=null)conflict("Only pending, unassigned requests can be edited.");r.update(body.title().trim(),body.category().trim(),body.location().trim(),body.description().trim(),body.priority());histories.save(new RequestHistory(r,u,"REQUEST_EDITED","Student updated request details"));return Dto.from(requests.save(r));}
 @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @Transactional public void delete(@AuthenticationPrincipal User u,@PathVariable Long id){MaintenanceRequest r=workflow.requireVisible(id,u);if(u.getRole()!=User.Role.STUDENT||r.getStatus()!=MaintenanceRequest.Status.PENDING||r.getAssignee()!=null)conflict("Only pending, unassigned requests can be deleted.");String attachment=r.getAttachmentId();requests.delete(r);requests.flush();files.delete(attachment);}
 @PostMapping(value="/multipart",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED) public Dto multipart(@AuthenticationPrincipal User u,@RequestPart("request") @Valid MaintenanceRequestController.CreateRequest body,@RequestPart(value="image",required=false) MultipartFile image){if(u.getRole()!=User.Role.STUDENT)deny();AttachmentStorage.Stored stored=files.save(image);try{MaintenanceRequest r=new MaintenanceRequest(u,body.title().trim(),body.category().trim(),body.location().trim(),body.description().trim(),body.priority());if(stored!=null)r.attach(stored.id(),stored.name(),stored.type(),stored.size());r=requests.save(r);histories.save(new RequestHistory(r,u,"REQUEST_CREATED","Request submitted"));return Dto.from(r);}catch(RuntimeException e){if(stored!=null)files.delete(stored.id());throw e;}}
 @PutMapping(value="/{id}/attachment",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @Transactional public Dto replace(@AuthenticationPrincipal User u,@PathVariable Long id,@RequestPart(value="image",required=false) MultipartFile image){MaintenanceRequest r=workflow.requireVisible(id,u);if(u.getRole()!=User.Role.STUDENT||r.getStatus()!=MaintenanceRequest.Status.PENDING||r.getAssignee()!=null)conflict("Attachment can only be changed while pending and unassigned.");AttachmentStorage.Stored stored=files.save(image);String old=r.getAttachmentId();if(stored==null)r.removeAttachment();else r.attach(stored.id(),stored.name(),stored.type(),stored.size());try{requests.saveAndFlush(r);files.delete(old);return Dto.from(r);}catch(RuntimeException e){if(stored!=null)files.delete(stored.id());throw e;}}
 @GetMapping("/{id}/image") public ResponseEntity<Resource> image(@AuthenticationPrincipal User u,@PathVariable Long id){MaintenanceRequest r=workflow.requireVisible(id,u);if(r.getAttachmentId()==null)throw new ResponseStatusException(HttpStatus.NOT_FOUND);Resource resource=new FileSystemResource(files.path(r.getAttachmentId()));if(!resource.exists())throw new ResponseStatusException(HttpStatus.NOT_FOUND);return ResponseEntity.ok().contentType(MediaType.parseMediaType(r.getAttachmentType())).header(HttpHeaders.CONTENT_DISPOSITION,"inline; filename=\""+r.getAttachmentName().replace("\"","")+"\"").body(resource);}
 @PatchMapping("/{id}/assignment") public Dto assign(@AuthenticationPrincipal User u,@PathVariable Long id,@RequestBody Assign body){User staff=body.staffId()==null?null:users.findById(body.staffId()).filter(x->x.getRole()==User.Role.STAFF&&x.isActive()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose an active staff member."));return Dto.from(workflow.assign(id,u,staff,body.priority()));}
 @PostMapping("/{id}/start") public Dto start(@AuthenticationPrincipal User u,@PathVariable Long id){return Dto.from(workflow.start(id,u));}
 @PostMapping("/{id}/complete") public Dto complete(@AuthenticationPrincipal User u,@PathVariable Long id,@RequestBody Complete body){return Dto.from(workflow.complete(id,u,body.repairNote()));}
 private void deny(){throw new ResponseStatusException(HttpStatus.FORBIDDEN);}private void conflict(String m){throw new ResponseStatusException(HttpStatus.CONFLICT,m);}
 public record Assign(Long staffId,MaintenanceRequest.Priority priority){} public record Complete(String repairNote){}
 public record Edit(@NotBlank @Size(max=120) String title,@NotBlank @Size(max=50) String category,@NotBlank @Size(max=150) String location,@NotBlank @Size(max=1200) String description,@NotNull MaintenanceRequest.Priority priority){}
 public record Dto(Long id,String title,String category,String location,MaintenanceRequest.Priority priority,MaintenanceRequest.Status status,Instant createdAt,long version,Person requester,Person assignee,boolean hasAttachment){static Dto from(MaintenanceRequest r){return new Dto(r.getId(),r.getTitle(),r.getCategory(),r.getLocation(),r.getPriority(),r.getStatus(),r.getCreatedAt(),r.getVersion(),Person.from(r.getUser()),Person.from(r.getAssignee()),r.getAttachmentId()!=null);}}
 public record Person(Long id,String name,String email){static Person from(User u){return u==null?null:new Person(u.getId(),u.getFullName(),u.getEmail());}}
 public record Detail(Dto request,String description,String repairNote,Instant completedAt,List<HistoryDto> history){}
 public record HistoryDto(Long id,String action,String details,String actor,Instant createdAt){static HistoryDto from(RequestHistory h){return new HistoryDto(h.getId(),h.getAction(),h.getDetails(),h.getActor()==null?"System":h.getActor().getFullName(),h.getCreatedAt());}}
}
